using System.IO;
using System.Windows;
using System.Windows.Controls;
using VisionPluginContracts;
internal static class Program {
 static int checks;
 static void Check(bool value,string message){checks++;if(!value)throw new Exception(message);}
 [STAThread] static void Main(){try{Run();}catch(Exception e){Console.Error.WriteLine(e);Environment.Exit(1);}}
 static void Run(){
  _=new Application();
  var folder=Path.Combine(AppContext.BaseDirectory,"Fixtures");var groups=File.ReadAllText(Path.Combine(folder,"Group.xml"));
  foreach(var (name,count) in new[]{("IMVSNPointCalibModu",3),("IMVSNImageCalibModu",3),("TranslationCalibModu",2),("RotateCalibModu",2),("ReadCalibFileModu",1)}){
   var definition=ToolConfigurationDefinition.Parse(File.ReadAllText(Path.Combine(folder,name+"AlgorithmTab.xml")),groups);var state=new ToolConfigurationState(definition);var registry=new ToolConfigurationControlRegistry();
   // Explicit test-only factories prove shell composition, not template parity.
   foreach(var type in state.Nodes.Select(n=>n.Element.Tag).Distinct()){state.RegisterDisplayTypeResolver(type,n=>n.Element.Tag);registry.Register(type,c=>{var b=new Button{Content=c.Node.CaptionKey,Tag=c.Node};b.Click+=(_,_)=>c.State.Invoke(c.Node);return b;});}
   using var view=new ToolConfigurationView(state,registry,localize:key=>key switch{"Tab_Basic Params"=>"基本参数","Tab_Run Params"=>"运行参数","ResultShow"=>"结果显示",_=>key});var window=new Window{Content=view,Width=420,Height=500,ShowInTaskbar=false};window.Measure(new Size(420,500));window.Arrange(new Rect(0,0,420,500));
   Check(view.Tabs.Items.Count==count,name+" tabs");Check(view.TabHeadersVisible==(count>1),name+" header");Check(view.Tabs.Items.OfType<TabItem>().All(t=>t.Width==76),name+" Chinese tab geometry");
   foreach(var t in view.Tabs.Items.OfType<TabItem>()){t.ApplyTemplate();var bd=(Border)t.Template.FindName("bd",t);var line=(System.Windows.Shapes.Rectangle)t.Template.FindName("line",t);Check(bd.Height==35,"source inner tab height35");Check(line.Height==2,"source underline2");Check(((System.Windows.Media.SolidColorBrush)line.Fill).Color.ToString()=="#FFE76900","source underline color");}
   view.Tabs.ApplyTemplate();var head=(Border)view.Tabs.Template.FindName("head",view.Tabs);Check(head.BorderThickness==new Thickness(0,0,0,1),"source header divider thickness");Check(((System.Windows.Media.SolidColorBrush)head.BorderBrush).Color.ToString()=="#FFCCC7C6","source divider color");
   if(count>1)Check(head.Margin==new Thickness(4,2,0,2),"source header margin");else Check(head.Height==0 && head.Visibility==Visibility.Hidden,"source single header zero hidden");
   var selectedTab=view.Tabs.Items.OfType<TabItem>().First();var selectedContent=(ContentControl)selectedTab.Template.FindName("Content",selectedTab);Check(selectedContent.FontWeight==FontWeights.Bold && selectedTab.FontSize==12,"source selected font");Check(((System.Windows.Media.SolidColorBrush)selectedContent.Foreground).Color.ToString()=="#FF4D4D4D","source selected foreground");Check(selectedTab.FontWeight==FontWeights.Normal,"header weight isolated from parameter content");var selectedBd=(Border)selectedTab.Template.FindName("bd",selectedTab);Check(((System.Windows.Media.SolidColorBrush)selectedBd.Background).Color.ToString()=="#20E76900","source selected background");
   if(name=="IMVSNPointCalibModu"){var outDir=Path.GetFullPath("analysis/full-audit/configuration-shell");Directory.CreateDirectory(outDir);var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap(420,500,96,96,System.Windows.Media.PixelFormats.Pbgra32);view.Measure(new Size(420,500));view.Arrange(new Rect(0,0,420,500));view.UpdateLayout();bitmap.Render(view);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap));using var stream=File.Create(Path.Combine(outDir,"source-derived-shell.png"));encoder.Save(stream);}
   Check(view.Diagnostics.Count==0,name+" registered shell no diagnostic");Check(view.DesiredConfigurationSize==new Size(420,500),"geometry delegated");Check(view.ChildMargin==new Thickness(32,1,32,0) && view.ChildHeaderMargin==new Thickness(32,0,0,8),"source Chinese margins");Check(view.RightCommands.Height==32 && view.LeftCommands.Height==32,"fixed footer32");Check(((StackPanel)view.RightCommands).Children.OfType<FrameworkElement>().All(c=>c.Margin.Top==4&&c.Margin.Bottom==4),"source footer inner margins");var shell=(Grid)view.Content;Check(((System.Windows.Media.SolidColorBrush)shell.Background).Color.ToString()=="#FFF2F3F5","source body background");Check(((System.Windows.Media.SolidColorBrush)((Grid)shell.Children[2]).Background).Color.ToString()=="#FFE4E5E7","source footer background");
   foreach(var tab in view.Tabs.Items.OfType<TabItem>()){Check(tab.Content is ScrollViewer{HorizontalScrollBarVisibility:ScrollBarVisibility.Disabled,VerticalScrollBarVisibility:ScrollBarVisibility.Auto},"scroll content");view.Tabs.SelectedItem=tab;Check(view.LeftCommands.Visibility==((string?)tab.Tag=="Tab_Run Params" && definition.LeftBottomCommands.Count>0?Visibility.Visible:Visibility.Collapsed),"run-only left commands");}
   var first=state.Nodes.First(n=>n.Element.Tag=="Tab");var same=view.Tabs.Items[0];state.SetProgrammatic(first,"CustomVisible","False");Check(ReferenceEquals(same,view.Tabs.Items[0]),"refresh preserves tree");Check(((TabItem)same).Visibility==Visibility.Collapsed,"refresh hides tab");window.Content=null;
  }
  var d=ToolConfigurationDefinition.Parse("<AlgorithmTabRoot><Tabs><Tab Name='A'><Categorys><Category Name='C'><Items><UnknownLeaf Name='X'/></Items></Category></Categorys></Tab></Tabs><BottomExcuteButtons><BottomCommand Name='Close'><CommandSetter><OperationName>ExcuteMethodOperation</OperationName><OperationParams>CloseParamsTabControl</OperationParams></CommandSetter></BottomCommand></BottomExcuteButtons></AlgorithmTabRoot>");
  var s=new ToolConfigurationState(d);s.RegisterDisplayTypeResolver("UnknownLeaf",n=>n.Get("DisplayType")??"UnknownLeaf");s.RegisterDisplayTypeResolver("Category",n=>n.Get("DisplayType")??"Category");using(var missing=new ToolConfigurationView(s,new ToolConfigurationControlRegistry(),"English")){Check(missing.Diagnostics.Count==2,"unknown explicit diagnostics");Check(missing.Diagnostics.All(x=>x.Code=="UnsupportedTemplate"),"no textbox fallback");Check(missing.Tabs.Items.OfType<TabItem>().Single().Width==110,"English tab width");Check(!missing.TabHeadersVisible,"one header hidden");Check(missing.ChildMargin==new Thickness(24,1,24,0),"source English margin");}
  var r=new ToolConfigurationControlRegistry();ToolConfigurationControlContext? saved=null;int refreshes=0;r.Register("UnknownLeaf",c=>{saved=c;c.OnRefresh(()=>refreshes++);return new TextBox{Text="keep"};});r.Register("BottomCommand",c=>new Button());
  using(var view=new ToolConfigurationView(s,r)){var window=new Window{Content=view};Check(saved?.OwnerWindow==window,"owner lazy lookup");Check(saved?.Element==s.Find("X")!.Element,"context source");var before=refreshes;s.SetProgrammatic("X","Enable","False");Check(refreshes>before,"factory refresh");Check(!((StackPanel)((ScrollViewer)((TabItem)view.Tabs.Items[0]).Content).Content).Children.OfType<StackPanel>().First().Children.OfType<TextBox>().Single().IsEnabled,"enable applied");s.SetProgrammatic("X","DisplayType","OtherTemplate");Check(view.Diagnostics.Any(x=>x.Code=="TemplateChanged" && x.TemplateKey=="OtherTemplate"),"changed template explicit");s.SetProgrammatic("C","DisplayType","CategoryNoHead");Check(((StackPanel)((StackPanel)((ScrollViewer)((TabItem)view.Tabs.Items[0]).Content).Content).Children[0]).Children.OfType<StackPanel>().First().Children.OfType<TextBlock>().Single().Visibility==Visibility.Collapsed,"category header nohead");window.Content=null;}
  s.SetProgrammatic("X","DisplayType","UnknownLeaf");
  var noheadDefinition=ToolConfigurationDefinition.Parse("<AlgorithmTabRoot><Tabs><Tab Name='A'><Categorys><CategoryNoHead Name='NoHeader'><Items><Integer Name='Count'/></Items></CategoryNoHead></Categorys></Tab></Tabs></AlgorithmTabRoot>");var noheadState=new ToolConfigurationState(noheadDefinition);var noheadRegistry=new ToolConfigurationControlRegistry();noheadRegistry.Register("Integer",_=>new TextBox());using(var noheadView=new ToolConfigurationView(noheadState,noheadRegistry)){Check(noheadView.Diagnostics.Count==0,"derived category is structural not unsupported leaf");var group=(StackPanel)((StackPanel)((ScrollViewer)((TabItem)noheadView.Tabs.Items[0]).Content).Content).Children[0];Check(group.Children.OfType<StackPanel>().First().Children.OfType<TextBlock>().Single().Visibility==Visibility.Collapsed,"derived CategoryNoHead hides header");}
  var panelDefinition=ToolConfigurationDefinition.Parse("<AlgorithmTabRoot><Tabs><Tab Name='Panel'><TabType>1</TabType><Categorys><Category Name='Empty'/><CategoryNoHead Name='PanelCategory'><Items><Integer Name='First'><Enable>False</Enable><CustomVisible>False</CustomVisible></Integer><Float Name='Extra'/></Items></CategoryNoHead><Category Name='Later'><Items><Boolean Name='Last'/></Items></Category></Categorys></Tab></Tabs></AlgorithmTabRoot>");
  var panelState=new ToolConfigurationState(panelDefinition);var constructed=new List<string?>();var panelRegistry=new ToolConfigurationControlRegistry();foreach(var key in new[]{"Integer","Float","Boolean"})panelRegistry.Register(key,c=>{constructed.Add(c.Node.Name);return new TextBox{Text=c.Node.Name,Margin=new Thickness(99)};});
  using(var panelView=new ToolConfigurationView(panelState,panelRegistry)) {
   Check(panelState.Find("Panel")!.IsPanel,"native TabType 1 is Panal");Check(!panelState.Find("First")!.CanSubscribe&&!panelState.Find("Extra")!.SubscribeVisible&&!panelState.Find("Last")!.SubscribeVisible,"all category rows in Panal suppress subscription");
   Check(constructed.SequenceEqual(new[]{"First"}),"Panal Collection[0] is flattened first leaf across categories, no extra construction");var content=((TabItem)panelView.Tabs.Items[0]).Content;
   Check(content is Grid&&content is not ScrollViewer,"Panal direct Grid rather than ordinary scroll/list shell");var direct=((Grid)content).Children.OfType<TextBox>().Single();Check(direct.Margin==new Thickness(0),"Panal ParamUserControl has source zero margin");Check(direct.Visibility==Visibility.Visible&&direct.IsEnabled,"Panal does not add ordinary ParamItemTemplate visibility/enable wrapper");
   panelState.SetProgrammatic("Panel","IsVisible","False");Check(((TabItem)panelView.Tabs.Items[0]).Visibility==Visibility.Collapsed,"native Tab.IsVisible hides panel tab");
  }
  var actualXml=File.ReadAllText(Path.Combine(folder,"IMVSColorSegmentModuAlgorithmTab.xml"));var actualDocument=System.Xml.Linq.XDocument.Parse(actualXml);var actualPanel=actualDocument.Root!.Element("Tabs")!.Elements("Tab").Single(t=>t.Element("TabType")?.Value=="1");
  var isolated=new System.Xml.Linq.XElement("AlgorithmTabRoot",new System.Xml.Linq.XElement("Tabs",new System.Xml.Linq.XElement(actualPanel)));var actualDefinition=ToolConfigurationDefinition.Parse(isolated.ToString());var actualState=new ToolConfigurationState(actualDefinition);
  using(var actualView=new ToolConfigurationView(actualState,new ToolConfigurationControlRegistry(),localize:k=>k=="Tab_Segment Params"?"分割参数":k)) {
   Check(actualState.Find("InputColorRange")!.Parent!.IsCategory,"original ColorSegment Collection[0] is ColorSegmentList leaf below CategoryNoHead");
   Check(actualView.Diagnostics.Count==1&&actualView.Diagnostics[0].TemplateKey=="ColorSegmentList","unimplemented native panel first leaf remains explicit Unsupported only once");
   var direct=(Grid)((TabItem)actualView.Tabs.Items[0]).Content;Check(direct.Children.Count==1&&direct.Children[0] is TextBlock block&&block.Text.Contains("ColorSegmentList"),"complex panel does not fall through to generic extra rows");
   var outDir=Path.GetFullPath("analysis/full-audit/configuration-shell");Directory.CreateDirectory(outDir);var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap(420,500,96,96,System.Windows.Media.PixelFormats.Pbgra32);actualView.Measure(new Size(420,500));actualView.Arrange(new Rect(0,0,420,500));actualView.UpdateLayout();bitmap.Render(actualView);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap));using var stream=File.Create(Path.Combine(outDir,"panal-source-derived-unsupported.png"));encoder.Save(stream);
  }
  var invalid=new ToolConfigurationControlRegistry();invalid.Register("UnknownLeaf",_=>new Window());try{using var view=new ToolConfigurationView(s,invalid);throw new Exception("Window allowed");}catch(InvalidOperationException){checks++;}
  var orderedDefinition=ToolConfigurationDefinition.Parse("<AlgorithmTabRoot><Tabs><Tab Name='Order'><Items><Integer Name='First'/><Integer Name='Second'/><Integer Name='Add'/></Items></Tab></Tabs></AlgorithmTabRoot>");
  var orderedState=new ToolConfigurationState(orderedDefinition);var orderedRegistry=new ToolConfigurationControlRegistry();orderedRegistry.Register("Integer",c=>new Button{Content=c.Node.Name,Tag=c.Element});
  using(var orderedView=new ToolConfigurationView(orderedState,orderedRegistry)){
   var panel=(StackPanel)((ScrollViewer)((TabItem)orderedView.Tabs.Items[0]).Content).Content;var original=panel.Children.OfType<Button>().ToArray();var first=orderedState.Find("First")!.Element;var add=orderedState.Find("Add")!.Element;
   orderedState.MoveBefore(first,add);
   Check(panel.Children.OfType<Button>().Select(b=>b.Content).SequenceEqual(new[]{"Second","First","Add"}),"runtime sibling order is reflected by common view");
   Check(ReferenceEquals(panel.Children[1],original[0]),"runtime move preserves editor instance and its callbacks");
   Check(first.Parent!.Children.Select(e=>e.Name).SequenceEqual(new[]{"First","Second","Add"}),"runtime move preserves immutable source order");
   Check(orderedState.GetChildren(first.Parent).Select(e=>e.Name).SequenceEqual(new[]{"Second","First","Add"}),"runtime collection exposes source-derived move order");
  }
  var composite=ToolConfigurationDefinition.Parse("<AlgorithmTabRoot><Tabs><Tab Name='A'><Items><PointPair Name='Pair'><ObjectPoint><CurValue>old</CurValue></ObjectPoint></PointPair><Integer Name='Other'/></Items></Tab></Tabs></AlgorithmTabRoot>");
  var compositeState=new ToolConfigurationState(composite);var compositeRegistry=new ToolConfigurationControlRegistry();Button? member=null;ToolConfigurationControlContext? parentContext=null;
  compositeRegistry.Register("PointPair",context=>{parentContext=context;var child=context.CreateChild(context.Element.Children.Single());member=new Button();child.OnRefresh(()=>member.Content=child.Node.Value);return member;});
  using(var compositeView=new ToolConfigurationView(compositeState,compositeRegistry)){
   Check(Equals(member!.Content,"old"),"composite child receives initial parent refresh");compositeState.SetProgrammatic(compositeState.GetNode(compositeState.Find("Pair")!.Element.Children.Single())!,"CurValue","new");
   Check(Equals(member.Content,"new"),"composite child refresh follows source identity");
   try{parentContext!.CreateChild(compositeState.Find("Other")!.Element);throw new Exception("Foreign composite child accepted");}catch(ArgumentException){checks++;}
  }
  Console.WriteLine($"VisionConfiguration.ViewChecks: {checks} checks passed");
 }
}
